AssistantMessageToolRequest(name='create', tool_call_id='function-call-0bd4af98-eb85-4b03-86e2-bc5eabe2e0d8', arguments={'file_text': ":root {
    --bg-color: #0a0a0a;
    --surface-color: #1a1a1a;
    --surface-accent: #2a2a2a;
    --text-primary: #f5f5f5;
    --text-secondary: #a0a0a0;
    --accent-color: #ffffff;
    --accent-hover: #e0e0e0;
    --error-color: #ff5252;
    --container-width: 1200px;
    --transition: all 0.3s ease;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Inter', sans-serif;
    background-color: var(--bg-color);
    color: var(--text-primary);
    line-height: 1.6;
    overflow-x: hidden;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 2rem;
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition);
}

ul {
    list-style: none;
}

img {
    max-width: 100%;
    display: block;
}

/* Header */
header {
    padding: 1.5rem 0;
    position: sticky;
    top: 0;
    z-index: 100;
    background-color: rgba(10, 10, 10, 0.8);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--surface-accent);
}

nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 2px;
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a:hover {
    color: var(--text-secondary);
}

.nav-actions {
    display: flex;
    gap: 1.5rem;
}

.nav-actions button {
    background: none;
    border: none;
    color: var(--text-primary);
    font-size: 1.2rem;
    cursor: pointer;
    position: relative;
}

#cart-count {
    position: absolute;
    top: -8px;
    right: -10px;
    background-color: var(--accent-color);
    color: var(--bg-color);
    font-size: 0.7rem;
    padding: 2px 6px;
    border-radius: 50%;
    font-weight: bold;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 0.8rem 2rem;
    border-radius: 4px;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    border: none;
}

.btn-primary {
    background-color: var(--accent-color);
    color: var(--bg-color);
}

.btn-primary:hover {
    background-color: var(--accent-hover);
}

.btn-secondary {
    background-color: transparent;
    color: var(--accent-color);
    border: 1px solid var(--accent-color);
}

.btn-secondary:hover {
    background-color: var(--accent-color);
    color: var(--bg-color);
}

.btn-small {
    padding: 0.5rem 1rem;
    font-size: 0.9rem;
}

/* Hero Section */
.hero {
    height: 80vh;
    display: flex;
    align-items: center;
    background: linear-gradient(rgba(0,0,0,0.5), rgba(0,0,0,0.5)), url('https://images.unsplash.com/photo-1511556820780-d912e42b4980?auto=format&fit=crop&q=80&w=1600') center/cover no-repeat;
    margin-bottom: 4rem;
}

.hero-content {
    max-width: 600px;
}

.hero h1 {
    font-size: 4rem;
    margin: 1rem 0;
    line-height: 1.1;
}

.hero p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.badge {
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 1px;
    color: var(--text-secondary);
}

/* Products Section */
.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2rem;
}

.view-all {
    color: var(--text-secondary);
    border-bottom: 1px solid var(--text-secondary);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
    margin-bottom: 4rem;
}

.product-card {
    background-color: var(--surface-color);
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
}

.product-card:hover {
    transform: translateY(-5px);
}

.product-image {
    aspect-ratio: 1;
    background-color: var(--surface-accent);
    position: relative;
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info {
    padding: 1.5rem;
}

.product-category {
    font-size: 0.75rem;
    color: var(--text-secondary);
    text-transform: uppercase;
}

.product-title {
    font-size: 1.1rem;
    margin: 0.5rem 0;
}

.product-price {
    font-weight: 700;
}

.add-to-cart {
    width: 100%;
    margin-top: 1rem;
}

/* Deals Section */
.deals-section {
    background-color: var(--surface-color);
    padding: 6rem 0;
    margin-bottom: 4rem;
}

.deals-card {
    background: linear-gradient(45deg, #1a1a1a, #2a2a2a);
    border-radius: 12px;
    padding: 4rem;
    text-align: center;
    border: 1px solid var(--surface-accent);
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.deals-content p {
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.countdown {
    display: flex;
    justify-content: center;
    gap: 2rem;
    margin-bottom: 2rem;
}

.time-box {
    display: flex;
    flex-direction: column;
}

.time-box span {
    font-size: 2rem;
    font-weight: 700;
}

.time-box label {
    font-size: 0.8rem;
    color: var(--text-secondary);
}

/* Editorial Section */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(2, 300px);
    gap: 1.5rem;
    margin-bottom: 6rem;
}

.editorial-card {
    position: relative;
    border-radius: 8px;
    overflow: hidden;
    background-color: var(--surface-accent);
}

.editorial-card.large {
    grid-row: span 2;
    background: url('https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&q=80&w=800') center/cover;
}

.editorial-card:nth-child(2) {
    background: url('https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&q=80&w=800') center/cover;
}

.editorial-card:nth-child(3) {
    background: url('https://images.unsplash.com/photo-1491553895911-0055eca6402d?auto=format&fit=crop&q=80&w=800') center/cover;
}

.card-overlay {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    padding: 2rem;
    background: linear-gradient(transparent, rgba(0,0,0,0.8));
}

.card-overlay h3 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
}

.card-overlay p {
    font-size: 0.9rem;
    color: var(--text-secondary);
    margin-bottom: 1rem;
}

/* Footer */
footer {
    padding: 4rem 0 2rem;
    border-top: 1px solid var(--surface-accent);
}

.footer-content {
    display: grid;
    grid-template-columns: 2fr 1fr 2fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-info p {
    margin-top: 1rem;
    color: var(--text-secondary);
}

.footer-links h4, .footer-newsletter h4 {
    margin-bottom: 1.5rem;
}

.footer-links ul li {
    margin-bottom: 0.8rem;
}

.footer-links a {
    color: var(--text-secondary);
}

.footer-links a:hover {
    color: var(--text-primary);
}

.footer-newsletter form {
    display: flex;
    gap: 0.5rem;
}

.footer-newsletter input {
    background-color: var(--surface-color);
    border: 1px solid var(--surface-accent);
    padding: 0.5rem 1rem;
    color: var(--text-primary);
    flex-grow: 1;
    border-radius: 4px;
}

.footer-bottom {
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.8rem;
    border-top: 1px solid var(--surface-accent);
    padding-top: 2rem;
}

@media (max-width: 768px) {
    .nav-links {
        display: none;
    }
    .hero h1 {
        font-size: 2.5rem;
    }
    .footer-content {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
    .editorial-grid {
        grid-template-columns: 1fr;
        grid-template-rows: auto;
    }
    .editorial-card.large {
        height: 400px;
    }
    .editorial-card.small {
        height: 250px;
    }
}
